#!/usr/bin/env node
/* Builds game/gameHtml.js: the web game from ../pocket-mochi inlined into a
   single HTML string that the app loads into its WebView.

   Run `npm run bundle-game` after changing anything in ../pocket-mochi.
   `npm run check-game` fails if game/gameHtml.js is out of date. */
const fs = require('fs');
const path = require('path');

const SRC = path.resolve(__dirname, '../../pocket-mochi');
const OUT = path.resolve(__dirname, '../game/gameHtml.js');
const read = (rel) => fs.readFileSync(path.join(SRC, rel), 'utf8');

function build() {
  let html = read('index.html');

  // Home-screen install tags only make sense for the browser version.
  html = html
    .split('\n')
    .filter((line) => !/rel="(manifest|icon|apple-touch-icon)"|name="(apple-mobile-web-app|mobile-web-app)/.test(line))
    .join('\n');

  html = html.replace(/<link rel="stylesheet" href="(css\/[^"]+)">/g, (_, file) => `<style>\n${read(file)}</style>`);

  // The app replaces the marker with the saved pet before loading the page,
  // so it has to sit in front of the first game script.
  let first = true;
  html = html.replace(/<script src="(js\/[^"]+)"><\/script>/g, (_, file) => {
    const code = read(file);
    if (/<\/script/i.test(code)) throw new Error(`${file} contains "</script", which would end the inline script early`);
    const marker = first ? '<!--PM_NATIVE_BOOT-->\n' : '';
    first = false;
    return `${marker}<script>\n${code}</script>`;
  });

  if (/(src|href)="(js|css)\//.test(html)) throw new Error('index.html still references a local file that was not inlined');
  if (first) throw new Error('No game scripts found in index.html');

  return '// Generated by scripts/bundle-game.js from ../pocket-mochi. Do not edit by hand.\n' +
    `export default ${JSON.stringify(html)};\n`;
}

const output = build();
if (process.argv.includes('--check')) {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (current !== output) {
    console.error('game/gameHtml.js is out of date. Run: npm run bundle-game');
    process.exit(1);
  }
  console.log('game/gameHtml.js is up to date.');
} else {
  fs.writeFileSync(OUT, output);
  console.log(`Wrote game/gameHtml.js (${(output.length / 1024).toFixed(1)} KB)`);
}
